sp_widget.client_script:
api.controller = function ($scope, snAnalytics) {
  var c = this;

  $scope.featureClicked = function (item) {
    if (!snAnalytics) return;

    var payload = {
      name: "GPA feature clicked",
      data: {
        feature_title: item.title,
        feature_href: item.href
      }
    };
    snAnalytics.addEvent(payload);
  };
};

sp_widget.css:
$gpa-bg: #f5f7fb;
$gpa-card-bg: #ffffff;
$gpa-border: #e2e8f0;
$gpa-primary: #0a1f61;
$gpa-primary-soft: rgba(10, 31, 97, 0.08);
$gpa-text-main: #0f172a;
$gpa-text-muted: #6b7280;

.gpa-features {
  margin: 4rem 0rem 4rem 0rem;
  background-color: $gpa-bg;
  padding: 6rem 0 !important;

  @media (min-width: 640px) {
    padding: 5rem 0;
  }
}

.gpa-features__inner {
  max-width: 100rem;
  margin: 0 auto;
  padding: 0 1.5rem;
}

/* Header */

.gpa-features__header {
  max-width: 60rem;
  margin: 0 auto 4rem;
}

.gpa-features__title {
  margin: 0 0 1rem;
  font-size: 3.5rem !important;
  font-weight: 700;
  color: $gpa-text-main;

  @media (min-width: 640px) {
    font-size: 2.5rem;
  }
}

.gpa-features__subtitle {
  margin: 0;
  font-size: 1.3rem !important;
  color: $gpa-text-muted;
}

/* Grid - Updated for 4 cards */

.gpa-features__grid {
  display: grid;
  grid-template-columns: repeat(1, minmax(0, 1fr)); // Mobile: 1 column
  gap: 2rem;

  @media (min-width: 768px) {
    grid-template-columns: repeat(2, minmax(0, 1fr)); // Tablet: 2 columns
  }

  @media (min-width: 1024px) {
    grid-template-columns: repeat(4, minmax(0, 1fr)); // Desktop: 4 columns
  }
}

/* Card */

.gpa-feature-card {
  background-color: $gpa-card-bg;
  border-radius: 1.25rem;
  border: 2px solid $gpa-border;
  padding: 1.75rem 1.75rem 1.5rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-shadow: 0 12px 30px rgba(15, 23, 42, 0.04);
  transition:
    border-color 0.18s ease,
    box-shadow 0.18s ease,
    transform 0.18s ease,
    background-color 0.18s ease;

  &:hover {
    border-color: rgba($gpa-primary, 0.55);
    box-shadow: 0 20px 45px rgba(15, 23, 42, 0.12);
    transform: translateY(-3px);
    background-color: #ffffff;
  }
}

.gpa-feature-card__header {
  margin-bottom: 1.5rem;
}

.gpa-feature-card__icon {
  width: 3rem;
  height: 3rem;
  border-radius: 0.9rem;
  background-color: $gpa-primary-soft;
  color: $gpa-primary;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1rem;
  font-size: 1.8rem !important;
}

.gpa-feature-card__title {
  margin: 0 0 0.4rem;
  font-size: 1.8rem !important;
  font-weight: 600;
  color: $gpa-text-main;
}

.gpa-feature-card__description {
  margin: 0;
  font-size: 1.3rem !important;
  line-height: 1.6;
  color: $gpa-text-muted;
}

/* Footer link */

.gpa-feature-card__footer {
  margin-top: 0.5rem;
}

.gpa-feature-card__link {
  display: inline-flex;
  align-items: center;
  font-size: 1.3rem !important;
  font-weight: 600;
  color: $gpa-primary;
  text-decoration: none;
  padding: 0;
  border: none;
  background: transparent;
  cursor: pointer;

  &:hover {
    text-decoration: underline;
  }
}

.gpa-feature-card__link-icon {
  margin-left: 0.4rem;
  font-size: 1rem !important;
}

sp_widget.script:
(function () {
  function optVal(opt, fallback) {
    if (!opt) return fallback || "";
    if (typeof opt === "string") return opt;
    if (opt.value) return opt.value;
    return fallback || "";
  }

  data.heading = optVal(options.heading, "Everything You Need to Succeed");
  data.subheading = optVal(
    options.subheading,
    "Our portal streamlines the grant application process from start to finish"
  );

  // ✅ UPDATED: 4 feature cards with improved content
  data.features = [
     {
      iconClass: "fa fa-file-text-o",
      title: "Browse Grant Programs",
      description: "Explore available funding opportunities tailored to your transportation projects.",
      href: "/applicant?id=opportunities_page"
    },
  ];
})();
